/// Whether a failed file's write left the run's own incomplete copy at the
/// destination, by the file's identity — its text, or its bytes when its
/// name is not UTF-8 (review cr-jl4fix2-1: two names of one text never
/// share the status): the record's lists, or what this machine's log said.
fn is_left_in_place(
    record: &RunRecord,
    logged: &HashSet<(String, Option<String>)>,
    path: &str,
    raw: Option<&str>,
) -> bool {
    let in_record = match raw {
        Some(raw) => record.left_in_place_raw.iter().any(|left| left == raw),
        None => record.left_in_place.iter().any(|left| left == path),
    };
    in_record || logged.contains(&(path.to_string(), raw.map(str::to_string)))
}

/// What this machine's log of a run says of the files whose write left
/// the run's own incomplete copy, when it was read.
#[derive(Default)]
struct LoggedLeftovers {
    /// A log of the run was found and read.
    read: bool,
    /// Every log of the run here is finished, ends with its `run-end` and
    /// lost nothing: it settles a file's status both ways.
    complete: bool,
    left: HashSet<(String, Option<String>)>,
    /// cr-ecm34-6, cr-ecm35-5: the failed files whose events do not say
    /// whether they left their copy, by identity: for those, `left` is not
    /// the answer.
    left_unknown: HashSet<(String, Option<String>)>,
    /// cr-ecm40-2: the files whose events SAY what their failure left — a
    /// failure with its disposition, a copy that landed it, a removal — by
    /// identity. A file the log never mentions is not among them: absent
