fn a_cancelled_audit_relay_cannot_attest_to_delivery() {
    let dir = tempfile::tempdir().unwrap();
    let log = RunLog::new(Some(LogPlace { dir:dir.path().into(), participant:"receiver".into(), keep:20, finished:None }),"r43-shutdown");
    log.start(Role::Destination,RunInfo::default(),None);
    let runtime = Builder::new_current_thread().enable_all().build().unwrap();
    runtime.block_on(async {
        let audit = RemoteTransferProgress::audit_only(log.audit_lane_at(End::Receiving).unwrap());
        audit.report_file_failed("p".into(),"read failed".into()).await;
    });
    drop(runtime);
    let runtime = Builder::new_current_thread().enable_all().build().unwrap();
    let report = runtime.block_on(log.close(Outcome::Failed,None,Some(RunTotals { files_failed:1, failed_paths_truncated:true, ..Default::default() }))).unwrap();
    let events: Vec<_> = open_log(&report.path.unwrap()).unwrap().map(|line|line.unwrap()).collect();
    let files = events.iter().filter(|line| matches!(line,LogLine::Event(event) if matches!(event.body,EventBody::FileFailed{..}))).count();
    let delivery = events.iter().find_map(|line| match line { LogLine::Event(event) => match &event.body { EventBody::Summary(summary) => Some(summary.all_events_logged), _ => None }, _ => None }).unwrap();
    println!("reported a file failure, observed {files}; summary all_events_logged {delivery}; caller complete {}",report.complete);
    assert!(!(report.complete || delivery), "cancelled delivery was certified");
}
