@'
use blit_core::job_log::{open_log, EventBody, LogLine, Outcome, Role, RunInfo};
use blit_core::remote::transfer::progress::RemoteTransferProgress;
use blit_core::run_log::{End, LogPlace, RunLog, RunTotals};

#[tokio::test]
async fn retrying_an_interrupted_close_waits_for_queued_events() {
    let dir = tempfile::tempdir().unwrap();
    let log = RunLog::new(Some(LogPlace { dir:dir.path().into(), participant:"receiver".into(), keep:20, finished:None }), "r43-reclose");
    log.start(Role::Destination,RunInfo::default(),None);
    let audit = RemoteTransferProgress::audit_only(log.audit_lane_at(End::Receiving).unwrap());
    let mut first = Box::pin(log.prepare_close(Outcome::Failed,None,None));
    tokio::select! {
        biased;
        _ = &mut first => panic!("the sender is still open"),
        _ = std::future::ready(()) => {}
    }
    drop(first);
    audit.report_file_failed("p".into(),"read failed".into()).await;
    drop(audit);
    let report = log.close(Outcome::Failed,None,Some(RunTotals { files_failed:1, failed_paths_truncated:true, ..Default::default() })).await.unwrap();
    let events: Vec<_> = open_log(&report.path.unwrap()).unwrap().map(|item|item.unwrap()).collect();
    let failures = events.iter().filter(|line|matches!(line,LogLine::Event(event) if matches!(event.body, EventBody::FileFailed{..}))).count();
    let delivered=events.iter().any(|line|matches!(line,LogLine::Event(event) if matches!(event.body, EventBody::Summary(summary) if summary.all_events_logged)));
    println!("events queued 1, failures on disk {failures}, all_events_logged {delivered}, report complete {}", report.complete);
    assert!(failures==1 || (!delivered && !report.complete));
}
'@ | Set-Content -LiteralPath $probePath
cargo test -p blit-core --test review_r43_reclose -- --nocapture *> "$copy/.review-checks/reclose.log"
$recloseExit=$LASTEXITCODE
Get-Content -Tail 18 "$copy/.review-checks/reclose.log"
"interrupted close probe exit $recloseExit"
Remove-Item -LiteralPath $probePath

