$reviewEnvKeys = @('TMPDIR','XDG_CACHE_HOME','GIT_TERMINAL_PROMPT','GH_NO_UPDATE_NOTIFIER','GIT_OPTIONAL_LOCKS')
$reviewOriginalEnv = @{}
foreach ($entry in [IO.File]::ReadAllText("/proc/$PID/environ").Split([char]0)) {
  $splitAt = $entry.IndexOf('=')
  if ($splitAt -gt 0 -and $reviewEnvKeys -contains $entry.Substring(0,$splitAt)) { $reviewOriginalEnv[$entry.Substring(0,$splitAt)] = $entry.Substring($splitAt+1) }
}
foreach ($key in $reviewEnvKeys) { [Environment]::SetEnvironmentVariable($key,$reviewOriginalEnv[$key],'Process') }
"Review session settings restored"

